/// MLP inference with float32 arithmetic (for verification)
pub fn mlp_predict_f32(features: &[f32; 27]) -> f32 {
    let mut h1 = [0.0_f32; 64];
    for i in 0..64 {
        let mut acc = 0.0_f32;
        for j in 0..27 {
            acc += features[j] * W_L1[i][j];
        }
        h1[i] = acc + B_L1[i];
        if h1[i] < 0.0 { h1[i] = 0.0; }  // ReLU
    }

    let mut h2 = [0.0_f32; 32];
    for i in 0..32 {
        let mut acc = 0.0_f32;
        for j in 0..64 {
            acc += h1[j] * W_L2[i][j];
        }
        h2[i] = acc + B_L2[i];
        if h2[i] < 0.0 { h2[i] = 0.0; }  // ReLU
    }

    let mut h3 = [0.0_f32; 16];
    for i in 0..16 {
        let mut acc = 0.0_f32;
        for j in 0..32 {
            acc += h2[j] * W_L3[i][j];
        }
        h3[i] = acc + B_L3[i];
        if h3[i] < 0.0 { h3[i] = 0.0; }  // ReLU
    }

    let mut out = 0.0_f32;
    for j in 0..16 {
        out += h3[j] * W_OUT[0][j];
    }
    out += B_OUT[0];
    1.0 / (1.0 + libm::expf(-out))
}